WITH page_agg AS ( SELECT cs.cs_catalog_page_sk, t.t_shift, SUM(cs.cs_net_profit) AS total_profit, SUM(cs.cs_sales_price) AS total_sales_price, COUNT(DISTINCT cs.cs_order_number) AS distinct_orders, AVG(CASE WHEN cs.cs_sales_price = 0 THEN 0 ELSE cs.cs_net_profit / cs.cs_sales_price END) AS profit_margin, CASE WHEN c.c_preferred_cust_flag = 'Y' THEN 'Preferred' ELSE 'Regular' END AS customer_type, COUNT(DISTINCT wp.wp_web_page_sk) AS web_page_cnt FROM catalog_sales cs JOIN time_dim t ON cs.cs_sold_time_sk = t.t_time_sk JOIN customer c ON cs.cs_bill_customer_sk = c.c_customer_sk LEFT JOIN web_page wp ON c.c_customer_sk = wp.wp_customer_sk WHERE cs.cs_net_profit IS NOT NULL GROUP BY cs.cs_catalog_page_sk, t.t_shift, c.c_preferred_cust_flag HAVING SUM(cs.cs_net_profit) > 0 ) SELECT p.cs_catalog_page_sk, p.t_shift, p.total_profit, p.total_sales_price, p.distinct_orders, p.profit_margin, p.customer_type, p.web_page_cnt, DENSE_RANK() OVER (PARTITION BY p.t_shift ORDER BY p.total_profit DESC) AS profit_rank_in_shift FROM page_agg p ORDER BY p.t_shift, profit_rank_in_shift LIMIT 20
